messages.content:
Berikut manifest game PajakRun — Endless Runner edukasi tentang pajak pusat vs daerah dengan tema Clean Modern dan kesulitan Normal.

```js
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "pajak-run", title: "PajakRun — Pusat vs Daerah", seed: "pajak-run-01",
  theme: { preset: "clean-modern" },

  learning: {
    subject: "Perpajakan Indonesia",
    concept: "Perbedaan pajak pusat dan pajak daerah berdasarkan lembaga pemungutnya",
    objectives: [
      "Mengelompokkan jenis pajak berdasarkan pemungutnya",
      "Meluruskan miskonsepsi bahwa Pajak Kendaraan Bermotor adalah pajak pusat"
    ],
    misconceptions: ["Pajak Kendaraan Bermotor dianggap pajak pusat"],
    mode: "category",
    categories: [
      { id: "pusat",  label: "Pajak Pusat",  color: "#2F80ED" },
      { id: "daerah", label: "Pajak Daerah", color: "#3FA34D" }
    ],
    items: [
      { id: "pph",         label: "PPh",                    category: "pusat",  explain: "Pajak Penghasilan dipungut pemerintah pusat atas penghasilan." },
      { id: "ppn",         label: "PPN",                    category: "pusat",  explain: "Pajak Pertambahan Nilai atas barang/jasa, dipungut pemerintah pusat." },
      { id: "bea-meterai", label: "Bea Meterai",            category: "pusat",  explain: "Pajak atas dokumen tertentu, dipungut pemerintah pusat." },
      { id: "pkb",         label: "Pajak Kendaraan Bermotor", category: "daerah", explain: "Dipungut pemerintah provinsi, jadi termasuk pajak daerah, bukan pusat." },
      { id: "pajak-hotel", label: "Pajak Hotel",            category: "daerah", explain: "Pajak daerah yang dipungut pemerintah kabupaten/kota." },
      { id: "pajak-resto", label: "Pajak Restoran",         category: "daerah", explain: "Pajak daerah yang dipungut pemerintah kabupaten/kota." },
      { id: "pbb-p2",      label: "PBB-P2",                 category: "daerah", explain: "PBB Perdesaan dan Perkotaan dipungut pemerintah daerah." }
    ],
    target: { rotateAfterCorrect: 5, bias: 0.5 }
  },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 3, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 360, maxSpeed: 720, accel: 6 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "surat-tagihan", w: 44, h: 48, weight: 3 },
      { type: "hazard", id: "denda",         w: 90, h: 24, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: true },
    hazard:  { lives: -1, sfx: "hit", shake: 8 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 15, speed: 25 }
  }
});
// END_OF_MANIFEST
```

Game ini mengajak pemain memilah item pajak sesuai target kategori (Pusat atau Daerah), dengan PKB sebagai jebakan utama miskonsepsi. Saya asumsikan rintangan "Surat Tagihan" dan "Denda" cukup generik sebagai penghalang tanpa makna belajar tambahan.
